package com.edward.galleryflow;
import android.content.*;import android.database.Cursor;import android.graphics.BitmapFactory;import android.net.Uri;import android.provider.OpenableColumns;import android.webkit.MimeTypeMap;import java.io.*;import java.security.*;import java.util.*;import java.util.zip.*;
/** Read-only virtual ZIP folders. Never resolves entry names as filesystem paths. */
final class ArchiveStore {
 static final String AUTH="com.edward.galleryflow.archives";static volatile boolean admin;
 static final long ZIP_LIMIT=512L*1024*1024,ENTRY_LIMIT=256L*1024*1024;static final int ENTRY_COUNT=20000;
 final Context context;final android.content.SharedPreferences prefs;final File root;
 ArchiveStore(Context c){context=c.getApplicationContext();prefs=c.getSharedPreferences("zip-locations",0);root=new File(c.getCacheDir(),"zip-browser");root.mkdirs();}
 static boolean virtual(Uri u){return u!=null&&AUTH.equals(u.getAuthority());}
 static String id(Uri u){List<String> parts=u.getPathSegments();if(parts.size()!=2||!parts.get(0).matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Invalid archive URI");return parts.get(0);}
 static String hash(String s){try{StringBuilder b=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)))b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static boolean safe(String s){if(s==null||s.startsWith("/")||s.contains("\\")||s.indexOf('\0')>=0)return false;for(String part:s.split("/"))if(part.equals("..")||part.equals("."))return false;return !s.contains(":");}
 static Uri uri(String id,String mode,String entry){return new Uri.Builder().scheme("content").authority(AUTH).appendPath(id).appendPath(mode).appendQueryParameter("entry",entry).build();}
 String key(Uri u){String id=id(u),entry=Objects.toString(u.getQueryParameter("entry"),"");String prefix=entry;if(u.getLastPathSegment().equals("file")){int slash=entry.lastIndexOf('/');prefix=slash<0?"":entry.substring(0,slash);}while(prefix.endsWith("/"))prefix=prefix.substring(0,prefix.length()-1);String base=prefs.getString(id+":key",null);if(base==null)throw new IllegalStateException("ZIP location no longer available");return base+(prefix.isEmpty()?"":"/"+prefix.toLowerCase(Locale.ROOT));}
 String accessKey(Uri u){String key=key(u);if("file".equals(u.getLastPathSegment())){String entry=Objects.toString(u.getQueryParameter("entry"),"");key+="/"+entry.substring(entry.lastIndexOf('/')+1).toLowerCase(Locale.ROOT);}return key;}
 void check(Uri u){if(!admin&&new LockStore(context).locked(accessKey(u)))throw new SecurityException("Archive folder is locked");}
 Uri open(Uri source,String name,String key)throws IOException{return open(source,name,key,null);}
 Uri open(Uri source,String name,String key,MediaRepository.Progress progress)throws IOException{synchronized(ArchiveStore.class){return openInternal(source,name,key,progress);}}
 private Uri openInternal(Uri source,String name,String key,MediaRepository.Progress progress)throws IOException{
  String id=hash(source.toString());String effective=key;String old=prefs.getString(id+":key",null);if(old!=null&&new LockStore(context).locked(old)&&!admin)throw new SecurityException("Archive is locked");
  if(!admin&&new LockStore(context).locked(effective))throw new SecurityException("Folder is locked");
  String stamp=stamp(source);File zip=new File(root,id+".zip");boolean fresh=!zip.exists()||!stamp.equals(prefs.getString(id+":stamp",""));
  if(fresh){File partial=new File(root,id+".part");try(InputStream in=context.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(partial)){if(in==null)throw new IOException("Cannot open ZIP");long expected=-1;try(Cursor c=context.getContentResolver().query(source,new String[]{OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst())expected=c.getLong(0);}catch(Exception ignored){}byte[] buffer=new byte[65536];long copied=0,reported=0;int count;while((count=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Loading canceled");copied+=count;if(copied>ZIP_LIMIT)throw new IOException("Archive size limit exceeded");out.write(buffer,0,count);if(progress!=null&&copied-reported>=1024*1024){progress.update(copied,expected);reported=copied;}}}catch(IOException e){partial.delete();throw e;}
   try(ZipFile test=new ZipFile(partial)){if(test.size()>ENTRY_COUNT)throw new IOException("ZIP has too many entries (maximum 20,000)");}catch(IOException e){partial.delete();throw new IOException("ZIP cannot be read. Encrypted or damaged archives are not supported.",e);}
   if(zip.exists()&&!zip.delete())throw new IOException("Cannot refresh ZIP cache");if(!partial.renameTo(zip))throw new IOException("Cannot cache ZIP");
   File[] cached=root.listFiles((d,n)->n.startsWith(id+"-"));if(cached!=null)for(File f:cached)f.delete();
  }
  prefs.edit().putString(id+":source",source.toString()).putString(id+":name",name).putString(id+":key",effective).putString(id+":stamp",stamp).commit();
  Set<String> ids=new HashSet<>(prefs.getStringSet("ids",Collections.emptySet()));ids.add(id);prefs.edit().putStringSet("ids",ids).commit();return uri(id,"dir","");
 }
 Uri cover(MediaRepository.Item item)throws IOException{Uri folder=item.uri;if(!virtual(folder)){String name=item.name.toLowerCase(Locale.ROOT);String k=item.key.endsWith("/"+name)||item.key.endsWith(":"+name)?item.key:item.key+"/"+name;folder=open(item.uri,item.name,k);}check(folder);String prefix=Objects.toString(folder.getQueryParameter("entry"),"");String first=null;LockStore locks=new LockStore(context);try(ZipFile z=new ZipFile(zip(folder))){Enumeration<? extends ZipEntry> entries=z.entries();while(entries.hasMoreElements()){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Loading canceled");ZipEntry e=entries.nextElement();String name=e.getName();if(e.isDirectory()||!safe(name)||!name.startsWith(prefix)||!mime(name).startsWith("image/")||e.getSize()>ENTRY_LIMIT)continue;Uri u=uri(id(folder),"file",name);if(!admin&&locks.locked(accessKey(u)))continue;if(first==null||AppSettings.naturalCompare(name,first)<0)first=name;}}return first==null?null:uri(id(folder),"file",first);}
 String stamp(Uri source){try(Cursor c=context.getContentResolver().query(source,null,null,null,null)){if(c!=null&&c.moveToFirst()){int size=c.getColumnIndex(OpenableColumns.SIZE),date=c.getColumnIndex("last_modified");return (size>=0?c.getLong(size):-1)+":"+(date>=0?c.getLong(date):-1);}}catch(Exception ignored){}return "unknown";}
 File zip(Uri u)throws IOException{check(u);String id=id(u);File f=new File(root,id+".zip");if(!f.exists()){String source=prefs.getString(id+":source",null);if(source==null)throw new FileNotFoundException("Archive unavailable");open(Uri.parse(source),prefs.getString(id+":name","ZIP"),prefs.getString(id+":key",""));}return f;}
 void removeLocation(Uri uri){Set<String> ids=new HashSet<>(prefs.getStringSet("ids",Collections.emptySet()));ids.remove(id(uri));prefs.edit().putStringSet("ids",ids).commit();}
 List<MediaRepository.Item> roots(){List<MediaRepository.Item> list=new ArrayList<>();for(String id:prefs.getStringSet("ids",Collections.emptySet())){Uri u=uri(id,"dir","");MediaRepository.Item i=new MediaRepository.Item(u,prefs.getString(id+":name","ZIP"),key(u),true,1);i.archive=true;i.document=true;i.path=i.name;list.add(i);}return list;}
 List<MediaRepository.Item> list(Uri folder)throws IOException{return list(folder,null);}
 List<MediaRepository.Item> list(Uri folder,MediaRepository.Progress progress)throws IOException{
  check(folder);String id=id(folder),prefix=Objects.toString(folder.getQueryParameter("entry"),"");if(!prefix.isEmpty()&&!prefix.endsWith("/"))prefix+="/";String label=prefs.getString(id+":name","ZIP");Map<String,MediaRepository.Item> out=new LinkedHashMap<>();LockStore locks=new LockStore(context);
  try(ZipFile zip=new ZipFile(zip(folder))){Enumeration<? extends ZipEntry> entries=zip.entries();int inspected=0;while(entries.hasMoreElements()){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Loading canceled");if(progress!=null&&inspected%16==0)progress.update(inspected,zip.size());if(++inspected>ENTRY_COUNT)throw new IOException("Too many archive entries");ZipEntry e=entries.nextElement();String name=e.getName();if(!safe(name)||!name.startsWith(prefix)||name.equals(prefix))continue;String tail=name.substring(prefix.length());int slash=tail.indexOf('/');boolean dir=slash>=0||e.isDirectory();String leaf=slash>=0?tail.substring(0,slash):tail;if(leaf.isEmpty()||out.containsKey(leaf))continue;String full=prefix+leaf;String mime=mime(full);if(!dir&&!mime.startsWith("image/")&&!mime.startsWith("video/"))continue;Uri u=uri(id,dir?"dir":"file",full+(dir?"/":""));String k=dir?key(u):key(folder);boolean hidden=!admin&&locks.locked(dir?k:accessKey(u));if(hidden&&!dir)continue;
    float ratio=1;if(!dir&&mime.startsWith("image/")&&e.getSize()<=ENTRY_LIMIT){try(InputStream stream=new LimitedInput(zip.getInputStream(e),1024*1024)){BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeStream(stream,null,opts);if(opts.outWidth>0&&opts.outHeight>0)ratio=(float)opts.outWidth/opts.outHeight;}catch(Exception ignored){}}
    MediaRepository.Item i=new MediaRepository.Item(u,leaf,k,dir,ratio);i.archive=true;i.document=true;i.video=mime.startsWith("video/");i.mime=mime;i.path=label+"!/"+full;i.size=Math.max(0,e.getSize());i.date=Math.max(0,e.getTime());out.put(leaf,i);
  }}List<MediaRepository.Item> list=new ArrayList<>(out.values());new AppSettings(context).sort(list);return list;
 }
 synchronized File materialize(Uri u)throws IOException{
  check(u);String entry=u.getQueryParameter("entry");if(!safe(entry)||!u.getLastPathSegment().equals("file"))throw new FileNotFoundException("Invalid ZIP entry");String id=id(u);String ext=entry.contains(".")?entry.substring(entry.lastIndexOf('.')).toLowerCase(Locale.ROOT):".bin";if(!ext.matches("\\.[a-z0-9]{1,8}"))ext=".bin";File out=new File(root,id+"-"+hash(entry)+ext);if(out.exists()){out.setLastModified(System.currentTimeMillis());return out;}
  try(ZipFile z=new ZipFile(zip(u))){ZipEntry e=z.getEntry(entry);if(e==null||e.isDirectory())throw new FileNotFoundException(entry);if(e.getSize()>ENTRY_LIMIT)throw new IOException("ZIP media entry exceeds 256 MB");trim();File partial=new File(root,out.getName()+".part");try(InputStream in=z.getInputStream(e);OutputStream stream=new FileOutputStream(partial)){copy(in,stream,ENTRY_LIMIT);}catch(IOException error){partial.delete();throw error;}if(!partial.renameTo(out))throw new IOException("Cannot prepare ZIP media");}
  check(u);return out;
 }
 void trim(){File[] files=root.listFiles((d,n)->!n.endsWith(".zip")&&!n.endsWith(".part"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long total=0;for(File f:files)total+=f.length();for(File f:files){if(total<256L*1024*1024)break;long size=f.length();if(f.delete())total-=size;}}
 static void copy(InputStream in,OutputStream out,long limit)throws IOException{byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Loading canceled");total+=n;if(total>limit)throw new IOException("Archive size limit exceeded");out.write(buffer,0,n);}}
 static String mime(String entry){int dot=entry.lastIndexOf('.');String ext=dot<0?"":entry.substring(dot+1).toLowerCase(Locale.ROOT);String type=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);return type==null?"application/octet-stream":type;}
 static final class LimitedInput extends FilterInputStream{long left;LimitedInput(InputStream in,long max){super(in);left=max;}public int read()throws IOException{if(left--<=0)return -1;return in.read();}public int read(byte[] b,int off,int len)throws IOException{if(left<=0)return -1;int n=in.read(b,off,(int)Math.min(left,len));if(n>0)left-=n;return n;}}
}

